#include <stdio.h>
/* ex08：目录检索效率——线性目录 vs 哈希目录
 * 树形目录下，打开 /a/b/c.txt 的做法是「逐级查目录」；
 * 每一级目录内部怎么找，决定了整体开销：
 *   线性表  -> 平均比较 (n+1)/2 次，命中靠前则快，靠后很慢
 *   B+ 树   -> log 级
 *   哈希表  -> 均摊 O(1)，但不支持前缀/范围查询
 * 本程序用比较次数把差别算出来。*/
int main(void) {
    int entries[] = {10, 100, 1000, 10000};
    printf("%-10s %-14s %-14s %-12s\n", "目录项数", "线性表(平均)", "线性表(最坏)", "哈希表(平均)");
    printf("---------------------------------------------------------\n");
    for (int i = 0; i < 4; i++) {
        int n = entries[i];
        printf("%-10d %-14d %-14d %-12d\n", n, (n + 1) / 2, n, 1);
    }
    printf("---------------------------------------------------------\n");
    printf("三级路径 /a/b/c.txt 的总比较次数（每级目录都 %d 项）:\n", 10000);
    int per_level_linear = (10000 + 1) / 2, per_level_hash = 1;
    printf("  线性目录: %d x 3 级 = %d 次比较\n", per_level_linear, per_level_linear * 3);
    printf("  哈希目录: %d x 3 级 = %d 次比较\n", per_level_hash, per_level_hash * 3);
    printf("  加速比 ≈ %d 倍\n", per_level_linear);
    printf("\n但哈希目录不能回答「列出所有 .log 文件」这种范围查询，所以现代文件系统的\n");
    printf("目录索引常用 B 树（ext4 的 htree、XFS 的 B+ 树）——兼顾点查与范围。\n");
    return 0;
}
